command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FRIEDVOLLE AURA (NURTI)
//
// - sicherer GM-Zwischenschritt mit gespeicherten Targets
// - Ziel- und Wirkender-Effekt direkt über Block 5
// - gekoppelte Effektanlage mit Rückrollung bei Teilfehler
// - Wirkungsende über Block 6 mit persistenten Daten
// - eine gemeinsame Karte über Block 19.8
// - roter GM-Button im verborgenen Bereich
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.BuildChanges ||
        !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Target?.Merken ||
        !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.BuildChanges ||
        !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.Token?.Finde || !DSK_FW?.Target?.Merken ||
        !DSK_FW?.Target?.Finden || !DSK_FW?.Target?.Actor ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Friedvolle Aura", vollerName = "Friedvolle Aura (Nurti)", ahne = "Nurti";
    const flagKey = "pendingFriedvolleAuraNurti", endeKey = "nurtiFriedvolleAura";
    const endeText = "Die friedvolle Aura verblasst, und die Modifikatoren sind aufgehoben.";
    const pause = ms => new Promise(resolve => setTimeout(resolve, Math.max(0, Number(ms) || 0)));

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    };

    const ladeZielActor = async daten => {
        if (!daten) return null;
        const token = await DSK_FW.Target.Finden(daten);
        return token?.actor || await DSK_FW.Target.Actor(daten);
    };

    const baueAuraChanges = qs => [
        ...DSK_FW.Effekt.BuildChanges(["Willenskraft"], "system.skillModifiers.FW", `-${qs * 4}`, qs),
        ...DSK_FW.Effekt.BuildChanges(
            ["system.rangeStats.attack", "system.meleeStats.attack"],
            "direkterSystemwert", `-${qs}`, qs
        )
    ];

    const erstelleBeschreibung = qs =>
        `Um das Nurtikind anzugreifen, muss der Angreifer eine um <b>${qs * 4}</b> ` +
        `(${qs} QS × 4) erschwerte Probe auf Willenskraft ablegen. Gelingt diese nicht, ` +
        `kann der Angreifer das Nurtikind nicht angreifen.` +
        `<br><br>Gelingt die Probe, sind Attacken gegen das Nurtikind dennoch um ` +
        `<b>${qs}</b> (${qs} QS) erschwert.` +
        `<br><br><b>Achtung:</b><br>Führt das Nurtikind während der Wirkungsdauer Angriffe ` +
        `oder sonstige offensive Handlungen gegen seine Feinde aus, bricht die Wirkung der Gabe ab.`;

    const findeAuraEffekte = (actor, { caster = false, casterUuid = null } = {}) =>
        (actor?.effects || []).filter(effect => {
            if (caster) {
                return effect.getFlag("dsk", "isFriedvolleAuraCaster") === true &&
                    (!casterUuid || effect.getFlag("dsk", "casterUuid") === casterUuid);
            }

            return effect.getFlag("dsk", "isFriedvolleAuraTarget") === true &&
                (!casterUuid || effect.getFlag("dsk", "casterUuid") === casterUuid);
        });

    const entferneAlteAuraEffekte = async (actor, optionen = {}) => {
        const effekte = findeAuraEffekte(actor, optionen);
        if (effekte.length) await actor.deleteEmbeddedDocuments("ActiveEffect", effekte.map(effect => effect.id));
    };

    // +++ 4 - ZIELEFFEKT DIREKT ÜBER BLOCK 5 +++++++++++++++++++

    const wendeZielEffektAn = async ({
        casterActor, casterName, targetActor, targetName,
        qs, dauerRunden, basisBeschreibung
    }) => {
        if (!casterActor || !targetActor) return null;

        await entferneAlteAuraEffekte(targetActor, { casterUuid: casterActor.uuid });

        const effektName = `${vollerName} - Aura von ${casterName}`;
        const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: effektName, ahne,
            beschreibung: `${basisBeschreibung}<br><hr><b>Aura wirkt von:</b> ${casterName}`,
            gabeZiel: "", qs, ziel: targetActor,
            changes: baueAuraChanges(qs),
            duration: {
                rounds: dauerRunden,
                startRound: game.combat?.round || 0,
                startTurn: game.combat?.turn || 0
            },
            showIcon: 1,
            flags: { dsk: {
                isFriedvolleAuraTarget: true,
                casterUuid: casterActor.uuid, casterName, targetName, qs,
                malusWillenskraft: qs * 4, malusAngriff: qs,
                schadensReaktion: endeKey,
                wirkungsende: {
                    sfName: endeKey, basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }}
        });

        if (!erzeugterEffekt) return null;

        const korrekteChanges = (erzeugterEffekt.changes || []).some(change =>
            change.key === "system.skillModifiers.FW"
        ) && (erzeugterEffekt.changes || []).some(change =>
            change.key === "system.rangeStats.attack"
        ) && (erzeugterEffekt.changes || []).some(change =>
            change.key === "system.meleeStats.attack"
        );

        const erfolgreich =
            erzeugterEffekt.getFlag("dsk", "isFriedvolleAuraTarget") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs &&
            korrekteChanges;

        if (!erfolgreich) {
            await erzeugterEffekt.delete();
            return null;
        }

        return erzeugterEffekt;
    };

    // +++ 5 - WIRKENDER-EFFEKT DIREKT ÜBER BLOCK 5 +++++++++++++

    const wendeCasterEffektAn = async ({
        casterActor, casterName, erfolgreicheNamen,
        qs, dauerRunden, basisBeschreibung
    }) => {
        if (!casterActor || !erfolgreicheNamen.length) return null;

        await entferneAlteAuraEffekte(casterActor, {
            caster: true, casterUuid: casterActor.uuid
        });

        const effektName = `${vollerName} - Wirkt gegen: ${erfolgreicheNamen.join(", ")}`;
        const zielListe = erfolgreicheNamen.map(name => `• ${name}`).join("<br>");

        const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: effektName, ahne,
            beschreibung: `${basisBeschreibung}<br><hr><b>Aura wirkt gegen:</b><br>${zielListe}`,
            gabeZiel: "", qs, ziel: casterActor, changes: [],
            duration: {
                rounds: dauerRunden,
                startRound: game.combat?.round || 0,
                startTurn: game.combat?.turn || 0
            },
            showIcon: 1,
            flags: { dsk: {
                isFriedvolleAuraCaster: true,
                casterUuid: casterActor.uuid, casterName, qs,
                zielNamen: foundry.utils.deepClone(erfolgreicheNamen),
                schadensReaktion: endeKey,
                wirkungsende: {
                    sfName: endeKey, basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }}
        });

        if (!erzeugterEffekt) return null;

        const erfolgreich =
            erzeugterEffekt.getFlag("dsk", "isFriedvolleAuraCaster") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs;

        if (!erfolgreich) {
            await erzeugterEffekt.delete();
            return null;
        }

        return erzeugterEffekt;
    };

    // +++ 6 - GM-ANFRAGE VERARBEITEN ++++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !game.user.isGM) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const dauerRunden = qs * 3;
        const dauerText = `${dauerRunden} Kampfrunden (${qs} QS × 3)`;
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const basisBeschreibung = erstelleBeschreibung(qs);
        const erfolge = [], erzeugteZielEffekte = [];
        const misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

        for (const zielDaten of daten.ziele || []) {
            const targetActor = await ladeZielActor(zielDaten);
            const targetName = zielDaten.name || targetActor?.name || "Unbekanntes Ziel";

            if (!targetActor) {
                misserfolge.push({ name: targetName, grund: "Zielakteur wurde nicht gefunden" });
                continue;
            }

            try {
                const effekt = await wendeZielEffektAn({
                    casterActor, casterName, targetActor, targetName,
                    qs, dauerRunden, basisBeschreibung
                });

                if (effekt) {
                    erzeugteZielEffekte.push(effekt);
                    erfolge.push({ name: targetName, rolle: "Betroffener Angreifer" });
                } else {
                    misserfolge.push({ name: targetName, grund: "Effekt konnte nicht angelegt werden" });
                }
            } catch (error) {
                console.error("Friedvolle Aura: Zieleffekt konnte nicht angelegt werden.", { zielDaten, error });
                misserfolge.push({ name: targetName, grund: "Fehler beim Anlegen des Effekts" });
            }

            await pause(1000);
        }

        // Gekoppelte Anlage: Ohne Wirkender-Effekt dürfen keine Zieleffekte bestehen bleiben.
        let casterEffekt = null;

        if (erfolge.length) {
            try {
                casterEffekt = await wendeCasterEffektAn({
                    casterActor, casterName,
                    erfolgreicheNamen: erfolge.map(eintrag => eintrag.name),
                    qs, dauerRunden, basisBeschreibung
                });
            } catch (error) {
                console.error("Friedvolle Aura: Wirkender-Effekt konnte nicht angelegt werden.", error);
            }
        }

        if (erfolge.length && !casterEffekt) {
            for (const effekt of erzeugteZielEffekte) {
                try {
                    const aktuell = effekt.parent?.effects?.get(effekt.id);
                    if (aktuell) await aktuell.delete();
                } catch (error) {
                    console.error("Friedvolle Aura: Rückrollung fehlgeschlagen.", { effekt, error });
                }
            }

            misserfolge.push(...erfolge.map(eintrag => ({
                name: eintrag.name,
                grund: "Gekoppelte Effektanlage konnte nicht abgeschlossen werden"
            })));

            erfolge.length = 0;
        }

        const erfolgreich = erfolge.length > 0;

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId, gabenName: vollerName, ahne,
            beschreibung: basisBeschreibung, wirkender: casterName,
            ziele: erfolge, misserfolge, dauerText, erfolgreich
        });

        if (erfolgreich) {
            ui.notifications.info(`Luna sagt 🌙: Friedvolle Aura wurde auf ${erfolge.length} Ziel(e) angewendet.`);
        } else {
            ui.notifications.error("Luna sagt 🌙: Friedvolle Aura konnte auf kein Ziel angewendet werden!");
        }

        return true;
    };

    // +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Akteur gefunden! Bitte wähle deinen Token aus.");
    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Konnte das Token des Wirkenden nicht finden!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Friedvolle Aura Probe", "Friedvolle Aura"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const dauerRunden = qs * 3;
    const dauerText = `${dauerRunden} Kampfrunden (${qs} QS × 3)`;
    const basisBeschreibung = erstelleBeschreibung(qs);

    // +++ 9 - TARGETS PRÜFEN UND SPEICHERN +++++++++++++++++++++

    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens einen möglichen Angreifer per Target aus!");
    }

    const gueltigeZiele = [], misserfolge = [];

    for (const targetToken of targets) {
        const targetActor = targetToken?.actor;
        const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Target";

        if (!targetActor) {
            misserfolge.push({ name: targetName, grund: "Kein gültiger Akteur" });
            continue;
        }

        if (targetActor.uuid === casterActor.uuid || targetActor.id === casterActor.id) {
            misserfolge.push({ name: targetName, grund: "Das Nurtikind kann nicht sein eigener Angreifer sein" });
            continue;
        }

        const zielDaten = DSK_FW.Target.Merken(targetToken);

        if (zielDaten) gueltigeZiele.push(zielDaten);
        else misserfolge.push({ name: targetName, grund: "Target konnte nicht gespeichert werden" });
    }

    // +++ 10 - KEIN GÜLTIGES ZIEL +++++++++++++++++++++++++++++

    if (!gueltigeZiele.length) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
            wirkender: casterName, ziele: [], misserfolge, dauerText,
            gmBereich: false, angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 11 - GEMEINSAME KARTE MIT ROTEM GM-BUTTON +++++++++++

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Aura anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung: basisBeschreibung, wirkender: casterName,
        ziele: gueltigeZiele.map(ziel => ({ name: ziel.name, rolle: "Möglicher Angreifer" })),
        misserfolge, dauerText, gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
    }

    // +++ 12 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName, qs,
        ziele: gueltigeZiele, misserfolge,
        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id, macroUuid
    };

    // +++ 13 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);

    // +++ 14 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);
    ui.notifications.info("Luna sagt 🌙: Die Anwendung der friedvollen Aura wurde bei der Spielleitung beantragt.");

}).call(this);
